/**
 * Problem - http://codeforces.com/contest/989/problem/A
 */

process.stdin.resume()
process.stdin.setEncoding('utf8')

var input_stdin = ''
var input_stdin_array = ''
var input_currentline = 0

process.stdin.on('data', function (data) {
  input_stdin += data
})

process.stdin.on('end', function () {
  input_stdin_array = input_stdin.split('\n')
  main()
})

function readLine() {
  return input_stdin_array[input_currentline++]
}

function main() {
  let input = readLine()
  process.stdout.write(doAppearInSomeCell(input))
  process.exit()
}

function doAppearInSomeCell(input) {
    if (input.length < 3) {
        return 'No'
    }

    let set = ['ABC', 'ACB', 'BAC', 'BCA', 'CAB', 'CBA']

    for (let i = 0 ; i < input.length ; i++) {
        let k = input.substring(i, i + 3)
        if (k.length === 3 && set.indexOf(k) !== -1) {
            return 'Yes'
        }
    }

    return 'No'
}
